# Guarda este archivo como api.py y arráncalo con:  uvicorn api:app --reload
import os
import hmac
import sqlite3
from datetime import datetime, timezone

import anthropic
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel, Field

# La clave de pago nunca se escribe aquí: se lee del entorno (los ajustes que
# guarda el ordenador fuera del código), así no acaba subida a internet sin querer.
API_KEY = os.environ.get("ANTHROPIC_API_KEY")
if not API_KEY:
    raise RuntimeError("Falta ANTHROPIC_API_KEY. Ponla antes de arrancar el servidor.")

cliente = anthropic.Anthropic(api_key=API_KEY)
app = FastAPI(title="Resumidor de textos", version="1.1")
CLIENT_TOKEN = os.environ.get("CLIENT_API_TOKEN", "")
if len(CLIENT_TOKEN) < 32:
    raise RuntimeError("CLIENT_API_TOKEN debe tener al menos 32 caracteres aleatorios")
DAILY_LIMIT = int(os.environ.get("DAILY_REQUEST_LIMIT", "100"))
USAGE_DB = os.environ.get("USAGE_DB", "api-usage.sqlite3")
class ClosingConnection(sqlite3.Connection):
    def __exit__(self, *args):
        try:
            return super().__exit__(*args)
        finally:
            self.close()

def authorize_and_reserve(token):
    if not hmac.compare_digest(token, CLIENT_TOKEN):
        raise HTTPException(status_code=401, detail="No autorizado")
    day = datetime.now(timezone.utc).date().isoformat()
    with sqlite3.connect(USAGE_DB, timeout=10, factory=ClosingConnection) as db:
        db.execute("CREATE TABLE IF NOT EXISTS usage(day TEXT PRIMARY KEY, count INTEGER NOT NULL)")
        db.execute("BEGIN IMMEDIATE")
        count = db.execute("SELECT count FROM usage WHERE day=?", (day,)).fetchone()
        if count and count[0] >= DAILY_LIMIT:
            raise HTTPException(status_code=429, detail="Cuota diaria agotada")
        db.execute("INSERT INTO usage VALUES (?,1) ON CONFLICT(day) DO UPDATE SET count=count+1", (day,))
        db.commit()



# El molde de lo que aceptamos. Lo que no encaje, FastAPI lo rechaza él solo.
class Peticion(BaseModel):
    texto: str = Field(min_length=20, max_length=8000)
    frases: int = Field(default=3, ge=1, le=10)


class Respuesta(BaseModel):
    resumen: str
    tokens_gastados: int


@app.post("/resumir", response_model=Respuesta)
def resumir(peticion: Peticion, x_client_token: str = Header(default="")):
    authorize_and_reserve(x_client_token)
    try:
        mensaje = cliente.messages.create(
            model="claude-haiku-4-5",
            max_tokens=600,
            system=f"Resume en exactamente {peticion.frases} frases. Sin preámbulo.",
            messages=[{"role": "user", "content": peticion.texto}],
        )
    except anthropic.RateLimitError:
        # Has pedido demasiadas cosas seguidas. Quien te llama puede reintentar.
        raise HTTPException(status_code=429, detail="Demasiadas peticiones, prueba en un minuto.")
    except anthropic.AuthenticationError:
        # Fallo tuyo, no de quien llama: no le cuentes por fuera qué ha pasado.
        raise HTTPException(status_code=500, detail="Error de configuración del servidor.")
    except anthropic.APIError as error:
        raise HTTPException(status_code=502, detail="Proveedor temporalmente no disponible")

    return Respuesta(
        resumen="".join(b.text for b in mensaje.content if b.type == "text"),
        tokens_gastados=mensaje.usage.input_tokens + mensaje.usage.output_tokens,
    )


@app.get("/salud")
def salud():
    return {"estado": "vivo"}
